//! Multiresolution builtins: modwt, imodwt, modwtmra, emd, vmd and ewt. Expected values come
//! from tool/refs/wavelet_mra/wavelet_mra.py (Percival-Walden MODWT checked against PyWavelets
//! swt, NumPy/SciPy implementations of Huang 1998 EMD, Dragomiretskiy-Zosso 2014 VMD and
//! Gilles 2013 EWT), printed into `refs`. Never MATLAB.
use matrust::{Array, Engine};
use refs::*;

const X24: &str = "cos((1:24)/3) + 0.1*(1:24)";
const X12: &str = "[0.5 -1.25 2 3.5 -0.75 1 0 2.25 -2 1.5 0.25 -0.5]";
const TWO: &str = "cos(2*pi*0.1*(0:499)') + cos(2*pi*0.02*(0:499)')";
const VSIG: &str = "cos(2*pi*0.05*(0:255)') + 0.5*cos(2*pi*0.2*(0:255)')";

fn values(e: &mut Engine, code: &str) -> Vec<f64> {
    e.execute(&format!("zz={code};"))
        .unwrap_or_else(|s| panic!("{code}: {s}"));
    match e.workspace().get("zz").unwrap() {
        Array::Numeric(m) => m.data().to_vec(),
        a => panic!("{code}: got {}", a.class()),
    }
}
fn dims(e: &mut Engine, code: &str) -> Vec<usize> {
    e.execute(&format!("zz={code};"))
        .unwrap_or_else(|s| panic!("{code}: {s}"));
    e.workspace().get("zz").unwrap().dims().to_vec()
}
fn run(e: &mut Engine, code: &str) {
    e.execute(code).unwrap_or_else(|s| panic!("{code}: {s}"));
}
fn error(code: &str) -> String {
    Engine::default()
        .execute(code)
        .err()
        .unwrap_or_else(|| panic!("{code}: expected an error"))
}
/// |got - want| <= tol * max(1, |want|) element by element.
fn all_close(got: &[f64], want: &[f64], tol: f64, what: &str) {
    assert_eq!(got.len(), want.len(), "{what}: lengths");
    for (i, (g, w)) in got.iter().zip(want).enumerate() {
        assert!(
            (g - w).abs() <= tol * w.abs().max(1.),
            "{what}[{i}]: got {g:.17e}, want {w:.17e}"
        );
    }
}
fn max_abs(v: &[f64]) -> f64 {
    v.iter().fold(0., |m, x| m.max(x.abs()))
}

#[test]
fn modwt_matches_the_percival_walden_reference() {
    let mut e = Engine::default();
    run(&mut e, &format!("x = {X24};"));
    assert_eq!(dims(&mut e, "modwt(x, 'db2', 2)"), [3, 24]);
    all_close(
        &values(&mut e, "modwt(x, 'db2', 2)"),
        &MODWT_DB2_X24,
        1e-12,
        "db2",
    );
    // Default wavelet sym4 and level floor(log2(24)) = 4; a column input gives the same rows.
    all_close(
        &values(&mut e, "modwt(x)"),
        &MODWT_SYM4_X24_DEFAULT,
        1e-12,
        "default",
    );
    all_close(
        &values(&mut e, "modwt(x')"),
        &MODWT_SYM4_X24_DEFAULT,
        1e-12,
        "column",
    );
    all_close(
        &values(&mut e, "modwt(x, 4)"),
        &MODWT_SYM4_X24_DEFAULT,
        1e-12,
        "lev only",
    );
    // Lo, Hi pair: the reconstruction filters of wfilters.
    run(&mut e, "[~, ~, lo, hi] = wfilters('db2');");
    all_close(
        &values(&mut e, "modwt(x, lo, hi, 2)"),
        &MODWT_DB2_X24,
        1e-12,
        "Lo/Hi",
    );
    // 'reflection': [x flip(x)], 2N columns.
    assert_eq!(
        dims(&mut e, &format!("modwt({X12}, 'haar', 2, 'reflection')")),
        [3, 24]
    );
    all_close(
        &values(&mut e, &format!("modwt({X12}, 'haar', 2, 'reflection')")),
        &MODWT_HAAR_X12_REFLECT,
        1e-12,
        "reflection",
    );
}

#[test]
fn modwt_inverse_is_perfect_and_energy_is_preserved() {
    let mut e = Engine::default();
    run(
        &mut e,
        "x = sin((1:50).^1.3/4) + 0.2*cos((1:50)*2.1) - 0.01*(1:50);",
    );
    for w in ["haar", "db4", "sym4", "coif2", "db10"] {
        run(&mut e, &format!("w = modwt(x, '{w}', 4);"));
        let err = values(&mut e, &format!("imodwt(w, '{w}') - x"));
        assert!(max_abs(&err) <= 1e-10, "{w}: {}", max_abs(&err));
        let energy = values(&mut e, "[sum(w(:).^2), sum(x.^2)]");
        assert!(
            (energy[0] - energy[1]).abs() <= 1e-10 * energy[1],
            "{w}: {energy:?}"
        );
        // modwtmra rows add up to x.
        assert_eq!(dims(&mut e, &format!("modwtmra(w, '{w}')")), [5, 50]);
        let err = values(&mut e, &format!("sum(modwtmra(w, '{w}'), 1) - x"));
        assert!(max_abs(&err) <= 1e-10, "{w} mra: {}", max_abs(&err));
    }
    // Default wavelet and level, column input: imodwt returns a row.
    run(&mut e, "w = modwt(x');");
    assert_eq!(dims(&mut e, "imodwt(w)"), [1, 50]);
    assert!(max_abs(&values(&mut e, "imodwt(w) - x")) <= 1e-10);
    // Reflection: imodwt and modwtmra keep the first N samples.
    run(
        &mut e,
        &format!("y = {X12}; w = modwt(y, 'db2', 3, 'reflection');"),
    );
    assert_eq!(dims(&mut e, "imodwt(w, 'db2', 'reflection')"), [1, 12]);
    assert!(max_abs(&values(&mut e, "imodwt(w, 'db2', 'reflection') - y")) <= 1e-10);
    assert_eq!(dims(&mut e, "modwtmra(w, 'db2', 'reflection')"), [4, 12]);
    assert!(
        max_abs(&values(
            &mut e,
            "sum(modwtmra(w, 'db2', 'reflection'), 1) - y"
        )) <= 1e-10
    );
}

#[test]
fn imodwt_level_and_modwtmra_match_the_reference() {
    let mut e = Engine::default();
    run(&mut e, &format!("x = {X24}; w = modwt(x, 'db2', 2);"));
    all_close(
        &values(&mut e, "imodwt(w, 'db2', 1)"),
        &IMODWT_DB2_LEV1,
        1e-12,
        "lev 1",
    );
    all_close(
        &values(&mut e, "modwtmra(w, 'db2')"),
        &MODWTMRA_DB2_X24,
        1e-12,
        "mra",
    );
}

#[test]
fn emd_separates_two_tones_and_reconstructs_exactly() {
    let mut e = Engine::default();
    run(&mut e, &format!("x = {TWO}; [imf, r, info] = emd(x);"));
    assert_eq!(dims(&mut e, "imf"), [500, EMD_SPLINE_SHAPE[0] as usize]);
    assert_eq!(dims(&mut e, "r"), [500, 1]);
    // Dominant frequency of each IMF (FFT bin) within 2 % of the tones 0.1 and 0.02.
    for (k, f) in [(1, 0.1), (2, 0.02)] {
        run(
            &mut e,
            &format!("s = abs(fft(imf(:, {k}))); [~, i] = max(s(1:250));"),
        );
        let p = values(&mut e, "(i - 1) / 500")[0];
        assert!((p - f).abs() <= 0.02 * f, "IMF {k}: {p}");
    }
    let err = values(&mut e, "sum(imf, 2) + r - x");
    assert!(max_abs(&err) <= 1e-12, "{}", max_abs(&err));
    all_close(&values(&mut e, "imf(:, 1)"), &EMD_SPLINE_IMF1, 1e-6, "imf1");
    all_close(&values(&mut e, "imf(:, 2)"), &EMD_SPLINE_IMF2, 1e-6, "imf2");
    assert_eq!(values(&mut e, "info.NumIMF"), [1., 2.]);
    assert_eq!(dims(&mut e, "info.NumSifting"), [2, 1]);
    // pchip envelopes; a row input still gives columns.
    run(&mut e, "[imf, r] = emd(x', 'Interpolation', 'pchip');");
    assert_eq!(dims(&mut e, "imf"), [500, EMD_PCHIP_SHAPE[0] as usize]);
    all_close(
        &values(&mut e, "imf(:, 1)"),
        &EMD_PCHIP_IMF1,
        1e-6,
        "pchip imf1",
    );
    assert!(max_abs(&values(&mut e, "sum(imf, 2) + r - x")) <= 1e-12);
    // Option limits: one IMF only, then the rest is the residual.
    run(
        &mut e,
        "[imf, r] = emd(x, 'MaxNumIMF', 1, 'SiftMaxIterations', 3, 'SiftRelativeTolerance', 0.01);",
    );
    assert_eq!(dims(&mut e, "imf"), [500, 1]);
    assert!(max_abs(&values(&mut e, "imf + r - x")) <= 1e-12);
    // A monotone signal has no IMF.
    run(&mut e, "[imf, r] = emd((1:20).^2);");
    assert_eq!(dims(&mut e, "imf"), [20, 0]);
    assert_eq!(dims(&mut e, "r"), [20, 1]);
}

#[test]
fn vmd_matches_the_reference_admm() {
    let mut e = Engine::default();
    run(&mut e, &format!("x = {VSIG};"));
    run(
        &mut e,
        "[u, r, info] = vmd(x, 'NumIMF', 2, 'InitializeMethod', 'grid');",
    );
    assert_eq!(dims(&mut e, "u"), [256, 2]);
    all_close(&values(&mut e, "u"), &VMD_GRID_IMF, 1e-6, "grid");
    all_close(
        &values(&mut e, "info.CentralFrequencies"),
        &VMD_GRID_CF,
        1e-6,
        "grid cf",
    );
    assert!(max_abs(&values(&mut e, "sum(u, 2) + r - x")) <= 1e-12);
    assert_eq!(values(&mut e, "info.ExitFlag"), [1.]);
    run(&mut e, "[u, r, info] = vmd(x', 'NumIMFs', 2);");
    all_close(&values(&mut e, "u"), &VMD_PEAKS_IMF, 1e-6, "peaks");
    all_close(
        &values(&mut e, "info.CentralFrequencies"),
        &VMD_PEAKS_CF,
        1e-6,
        "peaks cf",
    );
    run(
        &mut e,
        "u = vmd(x, 'NumIMFs', 3, 'PenaltyFactor', 500, 'AbsoluteTolerance', 1e-7, 'MaxIterations', 300, 'InitializeMethod', 'grid');",
    );
    all_close(&values(&mut e, "u"), &VMD_K3_IMF, 1e-6, "K=3");
    // 'random' draws from the rand stream: rng(seed) repeats the run.
    run(
        &mut e,
        "rng(7); a = vmd(x, 'NumIMFs', 3, 'InitializeMethod', 'random', 'MaxIterations', 40);",
    );
    run(
        &mut e,
        "rng(7); b = vmd(x, 'NumIMFs', 3, 'InitializeMethod', 'random', 'MaxIterations', 40);",
    );
    assert_eq!(values(&mut e, "max(abs(a(:) - b(:)))"), [0.]);
}

#[test]
fn ewt_matches_the_reference_filter_bank() {
    let mut e = Engine::default();
    run(&mut e, &format!("x = {VSIG};"));
    run(&mut e, "[mra, cfs] = ewt(x, 'MaxNumPeaks', 2);");
    assert_eq!(dims(&mut e, "mra"), [256, 2]);
    all_close(&values(&mut e, "mra"), &EWT_MP2_MRA, 1e-9, "mra");
    all_close(&values(&mut e, "cfs"), &EWT_MP2_CFS, 1e-9, "cfs");
    assert!(max_abs(&values(&mut e, "sum(mra, 2) - x")) <= 1e-10);
    // Default 70 % threshold keeps the stronger tone only: one band, the signal itself.
    run(&mut e, "mra = ewt(x');");
    assert_eq!(dims(&mut e, "mra"), [256, EWT_DEFAULT_SHAPE[0] as usize]);
    all_close(&values(&mut e, "mra"), &EWT_DEFAULT_MRA, 1e-9, "default");
    run(
        &mut e,
        "y = x + 0.3*cos(2*pi*0.33*(0:255)'); [mra, cfs] = ewt(y, 'MaxNumPeaks', 3, 'SegmentMethod', 'localmin', 'FrequencyResolution', 0.05);",
    );
    all_close(
        &values(&mut e, "mra"),
        &EWT_LOCALMIN_MRA,
        1e-9,
        "localmin mra",
    );
    all_close(
        &values(&mut e, "cfs"),
        &EWT_LOCALMIN_CFS,
        1e-9,
        "localmin cfs",
    );
    assert!(max_abs(&values(&mut e, "sum(mra, 2) - y")) <= 1e-10);
    // Shorter than 64 samples: zero-padded inside, cut back to N.
    run(
        &mut e,
        "s = cos((1:40)*0.9) + 0.5*cos((1:40)*2.4); mra = ewt(s, 'MaxNumPeaks', 2, 'LogSpectrum', true);",
    );
    all_close(&values(&mut e, "mra"), &EWT_SHORT_MRA, 1e-9, "short");
    assert!(max_abs(&values(&mut e, "sum(mra, 2) - s'")) <= 1e-10);
}

#[test]
fn multiresolution_errors_are_matlab_style() {
    for (code, part) in [
        ("modwt(1:8, 'bior2.2')", "orthogonal"),
        ("modwt(1:8, 'db2', 4)", "floor(log2(N))"),
        ("modwt([1 2; 3 4])", "vector"),
        ("modwt(1, 'db2')", "at least 2"),
        ("modwt(1:8, 'db2', 2, 'TimeAlign', true)", "TimeAlign"),
        ("modwt(1:8, 'db2', 2, 'circular')", "unknown option"),
        ("imodwt(modwt(1:8), 'db2', 9)", "reconstruction level"),
        ("imodwt([1 2 3; 4 5 6], 'reflection')", "even number"),
        ("emd(1:10, 'Foo', 1)", "unknown option 'Foo'"),
        ("emd(1:10, 'Interpolation', 'linear')", "spline"),
        ("emd(1:10, 'MaxNumIMF')", "pairs"),
        ("[a, b, c, d] = emd(1:10)", "too many output"),
        ("vmd(1:10, 'NumIMFs', 0)", "NumIMFs"),
        (
            "vmd(1:10, 'InitializeMethod', 'center')",
            "InitializeMethod",
        ),
        ("vmd(1:10, 'Foo', 2)", "unknown option"),
        ("emd(1:10, 'Max', 2)", "ambiguous"),
        (
            "vmd(1:10, 'NumIMFs', 2, 'CentralFrequencies', [0.1 0.2 0.3])",
            "elements",
        ),
        (
            "ewt(1:10, 'MaxNumPeaks', 2, 'PeakThresholdPercent', 50)",
            "not both",
        ),
        ("ewt(1:10, 'SegmentMethod', 'mid')", "SegmentMethod"),
        (
            "ewt(1:10, 'FrequencyResolution', 0.5)",
            "FrequencyResolution",
        ),
        ("[a, b, c] = ewt(1:10)", "not supported"),
    ] {
        let message = error(code);
        assert!(message.contains(part), "{code}: {message}");
    }
}

#[test]
fn review_b7_deep_modwt_coefficients_are_rejected() {
    for code in ["imodwt(zeros(66, 2))", "modwtmra(zeros(66, 2))"] {
        let message = error(code);
        assert!(message.contains("floor(log2(N))"), "{code}: {message}");
    }
    // A depth of floor(log2(N)) is still legal (2 rows => level 1, N = 2).
    let mut e = Engine::default();
    run(
        &mut e,
        "y = imodwt(zeros(2, 2)); z = modwtmra(zeros(2, 2));",
    );
    assert_eq!(dims(&mut e, "y"), [1, 2]);
    assert_eq!(dims(&mut e, "z"), [2, 2]);
}

#[test]
fn review_b7_modwt_kernels_observe_cancellation() {
    use std::sync::atomic::Ordering;
    use std::time::{Duration, Instant};
    // Zero-padded Haar, one legal level. The product is large; each kernel
    // polls about every 1e6 tap updates, so cancel returns in well under a second.
    let cases = [
        "lo=[1 1 zeros(1,30000)]; hi=[1 -1 zeros(1,30000)]; modwt(zeros(1,6000), lo, hi, 1)",
        "lo=[1 1 zeros(1,30000)]; hi=[1 -1 zeros(1,30000)]; imodwt(zeros(2,6000), lo, hi)",
    ];
    for code in cases {
        let mut e = Engine::default();
        let cancel = e.cancellation();
        let run = std::thread::spawn(move || {
            let result = e.execute(code);
            (result, Instant::now())
        });
        std::thread::sleep(Duration::from_millis(40));
        assert!(!run.is_finished(), "{code}: finished before cancel");
        let cancelled = Instant::now();
        cancel.store(true, Ordering::Relaxed);
        let (result, ended) = run.join().expect("modwt worker");
        let err = result.expect_err(code);
        assert!(err.contains("Calculation cancelled"), "{code}: {err}");
        let lag = ended.saturating_duration_since(cancelled);
        assert!(
            lag < Duration::from_millis(800),
            "{code}: cancel took {lag:?}"
        );
    }
}

#[test]
fn multiresolution_size_limits_are_refused_before_allocation() {
    let mut e = Engine::default();
    run(&mut e, "x = zeros(1000000, 1);");
    for code in [
        "n = numel(vmd(x, 'NumIMFs', 1000));",
        "n = numel(ewt(x, 'MaxNumPeaks', 1000));",
    ] {
        let started = std::time::Instant::now();
        let err = e.execute(code).unwrap_err();
        let elapsed = started.elapsed();
        assert!(elapsed.as_millis() < 1000, "{code} took {elapsed:?}: {err}");
        assert!(err.contains("element limit"), "{code}: {err}");
        assert!(!err.contains("Workspace"), "{code}: refused late: {err}");
        eprintln!("SIZE_LIMIT {err}");
    }
    run(&mut e, "y = zeros(2^24, 1);");
    let started = std::time::Instant::now();
    let err = e.execute("n = numel(modwt(y));").unwrap_err();
    let elapsed = started.elapsed();
    assert!(elapsed.as_millis() < 1000, "modwt took {elapsed:?}: {err}");
    assert!(err.contains("element limit"), "modwt: {err}");
    assert!(!err.contains("Workspace"), "modwt: refused late: {err}");
    eprintln!("SIZE_LIMIT {err}");
    // Real kernels on 1e5 samples, timed in this gate build.
    run(
        &mut e,
        "t = (0:99999)'; s = cos(2*pi*0.05*t) + 0.5*cos(2*pi*0.2*t);",
    );
    let started = std::time::Instant::now();
    run(&mut e, "w = modwt(s); xrec = imodwt(w);");
    let modwt_ms = started.elapsed().as_secs_f64() * 1e3;
    // imodwt returns a row; s is a column.
    let recon = max_abs(&values(&mut e, "xrec - s'"));
    assert!(recon <= 1e-8, "modwt recon {recon}");
    let started = std::time::Instant::now();
    run(&mut e, "[u, r] = vmd(s, 'NumIMFs', 2);");
    let vmd_ms = started.elapsed().as_secs_f64() * 1e3;
    let recon = max_abs(&values(&mut e, "sum(u, 2) + r - s"));
    assert!(recon <= 1e-8, "vmd recon {recon}");
    eprintln!("modwt/vmd 1e5: modwt {modwt_ms:.1} ms, vmd {vmd_ms:.1} ms");
}

#[test]
fn review_b7_ewt_admits_complex_scratch_before_fft() {
    // Length 128 is padded to 128. One column plus three complex FFT buffers
    // is 1345 doubles, over 8 KiB (1024 doubles), with or without MaxNumPeaks.
    // Length 64 (673 doubles) fits and still runs.
    let mut e = Engine::with_limits(matrust::engine::Limits {
        evaluation_units: None,
        memory_bytes: 8 * 1024,
        ..matrust::engine::Limits::browser()
    });
    for code in [
        "n = numel(ewt(zeros(128, 1), 'MaxNumPeaks', 1));",
        "n = numel(ewt(zeros(128, 1)));",
    ] {
        let started = std::time::Instant::now();
        let err = e.execute(code).unwrap_err();
        assert!(
            started.elapsed().as_millis() < 1000,
            "{code} took too long: {err}"
        );
        assert!(err.contains("memory limit"), "{code}: {err}");
        assert!(!err.contains("Workspace"), "{code}: {err}");
    }
    run(&mut e, "y = ewt(zeros(64, 1), 'MaxNumPeaks', 1);");
    assert_eq!(dims(&mut e, "numel(y)"), [1, 1]);
    run(&mut e, "z = ewt(zeros(64, 1));");
    assert!(values(&mut e, "numel(z)")[0] >= 64.);
}

